#' Match on treatment history using a two-tier exact matching strategy.
#'
#' @description
#' Performs a hierarchical matching process with configurable tiers.
#' Each tier specifies which variables to exact-match on, in addition to
#' treatment history (generated by md_prep_match).
#' Orphans (unmatched treated units) cascade to the next tier.
#'
#' previous default tiers:
#'   Tier 1: history + Nationality + Gender
#'   Tier 2: history only
#'
#' @param dt A data.table containing the panel data.
#' @param L Integer. The number of lags of treatment history to match on.
#' @param treatment_col String. The column name of the treatment variable.
#' @param history_col String. The column name for the cumulative history variable.
#' @param uid String. The column name of the unit identifier.
#' @param tid String. The column name of the time identifier.
#' @param tiers List of character vectors. Each element specifies the column
#'   names to exact-match on (combined with hist_str) for that tier.
#'   e.g.: list(c("hist_str", "Nationality", "Gender"), c("hist_str")).
#' @param return_type Option: "summary", "matches", "matches-info".
#' @return A data.table containing either summary statistics or all matched pairs.
gd_match_history <- function(dt_panel, L, treatment_col, history_col,
                             uid, tid, tiers,
                             return_type = "summary") {

  ## dt  
  dt_d <- md_prep_match(dt_panel, L, treatment_col, history_col, uid, tid)
  dt_matched <- data.table()
  

  for (tier_n in seq_along(tiers)) {
    tier_vars <- tiers[[tier_n]]
    key_col <- paste0("tier", tier_n, "_key")

    ## create exact-match key for this tier
    dt_d[, (key_col) := collapse::finteraction(.SD, sep = "_"), .SDcols = tier_vars]

    if (tier_n == 1) {
      dt_tier <- gd_tier_match(dt_d, key_col, return_type = return_type, tier = tier_n)
      dt_matched <- dt_tier
    } else {
      ## orphans from previous tier
      matched_uid <- if (return_type == "summary") {
        unique(dt_matched$uid)
      } else unique(dt_matched$treated_id)
      dt_orphans <- dt_d[treat_bin == 1 & !(uid %in% matched_uid)]
      if (nrow(dt_orphans) == 0) break

      dt_tier <- gd_tier_match(dt_orphans, key_col,
                               controls_pool = dt_d[treat_bin == 0],
                               return_type = return_type, tier = tier_n)
      dt_matched <- rbind(dt_matched, dt_tier, fill = TRUE)
    }
  }

  if (return_type == "summary") return(gd_match_summary(dt_d, dt_matched))
  dt_matched
}

#' Execute matching for a single year within a tier.
#'
#' @description
#' Given treated and control units in a single year, joins them on the
#' given key column and formats the result according to return_type.
#'
#' @param yr Integer year to process.
#' @param dt_units data.table of all units (or orphaned treated units for Tier 2).
#' @param controls_pool Optional separate pool of controls (used for Tier 2).
#' @param key_col String name of the column to join on.
#' @param return_type One of "summary", "matches", "matches-info".
#' @param tier Integer tier number (1 or 2).
#' @return data.table of matched pairs, or NULL if no matches exist.
gd_ematch_yr <- function(yr, dt_units, controls_pool, key_col, return_type, tier) {
  ## extract treated and control pools for this year via binary search
  ## browser()
  dt_trtd <- dt_units[.(yr, 1L), on = c("tid", "treat_bin"), nomatch = NULL]
  dt_ctrls <- if (is.null(controls_pool)) {
    dt_units[.(yr, 0L), on = c("tid", "treat_bin"), nomatch = NULL]
  } else {
    controls_pool[.(yr), on = "tid", nomatch = NULL]
  }

  if (nrow(dt_trtd) == 0 || nrow(dt_ctrls) == 0) return(NULL)

  ## xx <- dt_ctrls[dt_trtd, .(control_id = uid, treated_id = i.uid, year = yr,
  ##                                              match_key = get(key_col), match_tier = tier),
  ##                                   on = key_col, nomatch = NULL, allow.cartesian = TRUE]

  ## yy <- join(dt_ctrls[, .(control_id = uid, year = yr, match_key = get(key_col), match_tier = tier)],
  ##            dt_trtd[, .(treated_id = uid, match_key = get(key_col))],
  ##            on = "match_key", how = "right", multiple = T)

  ## yy[!xx, on = "match_key"]


  ## yy[!xx[, .(match_key = funique(match_key))], on = "match_key"]

  

  ## zz <- join(dt_ctrls[, .(control_id = uid, year = yr, match_key = get(key_col), match_tier = tier)],
  ##            dt_trtd[, .(treated_id = uid, match_key = get(key_col))],             
  ##            on = "match_key", how = "inner", multiple = T)


  switch(return_type,
         summary = dt_ctrls[dt_trtd, .(uid = i.uid, N = .N), on = key_col,
                            nomatch = NULL, by = .EACHI][N > 0],
         ## `matches-info` = dt_ctrls[dt_trtd, .(control_id = uid, treated_id = i.uid, year = yr,
         ##                                       match_key = get(key_col), match_tier = tier),
         ##                            on = key_col, nomatch = NULL, allow.cartesian = TRUE],
         `matches-info` = join(dt_ctrls[, .(control_id = uid, year = yr, match_key = get(key_col), match_tier = tier)],
                               dt_trtd[, .(treated_id = uid, match_key = get(key_col))],             
                               on = "match_key", how = "inner", multiple = T),
         matches = dt_ctrls[dt_trtd, .(control_id = uid, treated_id = i.uid, year = yr),
                            on = key_col, nomatch = NULL, allow.cartesian = TRUE])

}

#' Execute tier matching by applying year-by-year joins.
#'
#' @description
#' Iterates over years and calls gd_ematch_yr for each.
#' Combines all years into a single data.table.
#'
#' @param dt_units data.table of units (must have tid and treat_bin columns).
#' @param key_col Column name for the exact-match key.
#' @param controls_pool Optional separate control pool.
#' @param return_type One of "summary", "matches", "matches-info".
#' @param tier Integer tier number.
#' @return data.table of matched pairs across all years.
gd_tier_match <- function(dt_units, key_col, controls_pool = NULL,
                          return_type = "summary", tier = 1) {
  ## browser()
  ## key on (tid, treat_bin) for O(log n) year subsetting instead of O(n) scan
  setkeyv(dt_units, c("tid", "treat_bin"))
  if (!is.null(controls_pool)) setkeyv(controls_pool, "tid")

  years <- sort(funique(dt_units$tid))

  rbindlist(lapply(years, function(yr) {
    gd_ematch_yr(yr, dt_units, controls_pool, key_col, return_type, tier)
  }), fill = TRUE)

}

#' Calculate summary statistics from matched pairs.
#'
#' @param dt_d Prepared data (must have treat_bin and uid columns).
#' @param dt_matches Summary-mode match output (with uid and N columns).
#' @return data.table with total_treated, treated_matched, avg_matches_per_treated, total_matches.
gd_match_summary <- function(dt_d, dt_matches) {
  data.table(
    total_treated = uniqueN(dt_d[treat_bin == 1, uid]),
    treated_matched = uniqueN(dt_matches$uid),
    avg_matches_per_treated = if (uniqueN(dt_matches$uid) > 0) {
      sum(dt_matches$N) / uniqueN(dt_matches$uid)
    } else 0,
    total_matches = sum(dt_matches$N)
  )
}

#' Prepare panel data for matching by constructing lagged history strings.
#'
#' @description
#' Renames unit and time IDs for internal use, creates binary treatment
#' indicator, generates L lags of the cumulative history variable, and
#' concatenates them into a string key for exact matching.
#'
#' @param dt Raw panel data.table.
#' @param L Number of lags.
#' @param t_col Treatment column name.
#' @param h_col History (cumulative) column name.
#' @param uid Unit ID column name.
#' @param tid Time ID column name.
#' @return Modified copy of dt with uid, tid, treat_bin, lag_* and hist_str columns.
md_prep_match <- function(dt_panel, L, t_col, h_col, uid, tid) {
  ## browser()
  dt_d <- copy(dt_panel)
  setnames(dt_d, c(uid, tid), c("uid", "tid"))
  dt_d <- dt_d[order(uid, tid)]

  dt_d[, treat_bin := as.integer(get(t_col) > 0)]

  ## L lags of pre-treatment history: caller ensures history_col represents
  ## state at start of year t (e.g. cumulative counts), so lag₀ is current.
  lag_offsets <- 0:(L - 1)
  lag_cols <- paste0("lag_", lag_offsets)

  if (nrow(dt_d) == 0) {
    dt_d[, (lag_cols) := shift(get(h_col), lag_offsets), by = uid]
    dt_d[, hist_str := collapse::finteraction(.SD, sep = "_"), .SDcols = lag_cols]
    return(dt_d)
  }

  dt_lag <- collapse::L(dt_d, by = ~uid, n=lag_offsets, cols = h_col) %>% copy %>% 
    .[, paste0("L0.", h_col) := get(h_col)] %>% 
    setnames(old = paste0("L", lag_offsets, ".", h_col), new = paste0(lag_cols))

  dt_d2 <- cbind(dt_d, dt_lag[, ..lag_cols])

  ## dt_d2[Xlag_1 != lag_1 | Xlag_2 != lag_2 | Xlag_0 != lag_0 ]

  
  ## dt_d3 <- dt_d2[complete.cases(dt_d2[, ..lag_cols])]

  dt_d3 <- collapse::na_omit(dt_d2, cols = lag_cols)

  ## dt_d3[, hist_str := do.call(paste, c(.SD, sep = "_")), .SDcols = lag_cols]
  dt_d3[, hist_str := collapse::finteraction(.SD, sep = "_"), .SDcols = lag_cols]
  ## dt_d3[hist_str != hist_intr]
  return(dt_d3)
}

#' @description
#' Constructs the long-format table used by CEM refinement. Each row is
#' one observation in a matched set: control rows (one per control × set)
#' and treated rows (one per unique treated × year). The `set` column
#' identifies which treated unit and year the row belongs to.
#'
#' @param dt_match Data.table from gd_match_history(matches-info).
#' @param uid String. Column name for the unit identifier (used in output).
#' @param tid String. Column name for the time identifier.
#' @return data.table with columns: uid, tid, treat, set, treated_id.
gd_build_dt_long <- function(dt_match, uid, tid) {
  ## first construct sets: each treated only once per TID
  ## each treated unit once per time period (saves ~1.2s over head(.SD,1) per treated_id)

  dt_set <- dt_match[, funique(.SD), .SDcols = c("treated_id", tid)] %>%
    setnames(old = tid, new = "tid") %>%
    ## .[, set := paste0(treated_id, "_", tid)]
    .[, set := collapse::finteraction(treated_id, tid, sep = "_")]

  ## microbenchmark(
  ##   oo <- dt_match[, .(uid = control_id, tid = get(tid), treat = 0, treated_id)],
  ##   kk <- dt_match[, .(uid = control_id, tid = ..tid, treat = 0, treated_id)],
  ##   times = 10)
  ## huh get(tid) is faster

  ## join controls to sets, then add treated themselves
  join(dt_match[, .(uid = control_id, tid = get(tid), treat = 0, treated_id)],
       dt_set, on = c("treated_id", "tid")) %>%
    rbind(dt_set[, .(uid = treated_id, treated_id, tid, set, treat = 1)])  ## add treated themselves
}


#' Extract breakpoints from a cutpoint specification for one covariate.
#'
#' @param v Covariate name.
#' @param cutpoints Named list mapping covariate names to integer bins or numeric breaks.
#' @param dt_ref Reference data.table containing the covariate column.
#' @return Numeric vector of breakpoints.
gd_extract_breaks <- function(v, cutpoints, dt_ref) {
  cp <- cutpoints[[v]]
  if (is.null(cp)) stop("gd_refine_matches: cutpoints must specify a value for ", v)
  if (is.numeric(cp) && length(cp) == 1) {
    seq(range(dt_ref[[v]], na.rm = TRUE)[1], range(dt_ref[[v]], na.rm = TRUE)[2],
        length.out = cp + 1)[2:cp]
  } else cp
}

#' Refine matches using Coarsened Exact Matching (CEM) — data.table version.
#'
#' @description
#' Pure data.table implementation matching the MatchIt::matchit(method = "cem")
#' algorithm. Coarsens each covariate into bins, then exact-matches on
#' (set × coarse bins). Cells with both treated and control units are kept;
#' cells with only one type are discarded.
#'
#' The cutpoints argument controls binning:
#'   - integer value (e.g., 8L): equal-width bins on the long data (matching matchit CEM)
#'   - numeric vector: explicit breakpoints (e.g., from gd_coarse_breaks)
#'
#' For diagnostics, the `matchit` slot wraps the results (subclass + weights)
#' in a backwards-compatible list mimicking a matchit object.
#'
#' @param dt_match Data.table of raw matches (control_id, treated_id, year).
#'   Must contain match_tier column (from matches-info mode).
#' @param dt_full The full panel data containing covariates.
#' @param covariates Character vector. Covariates for refinement.
#' @param cutpoints Named list. Names are covariate names, values are
#'   integers (equal-width bins) or numeric vectors (explicit breakpoints).
#' @param uid String. Column name for the unit identifier in dt_full.
#'   Must also match the id used in dt_match (via control_id/treated_id).
#' @param tid String. Column name for the time identifier in dt_full and dt_match.
#' @return A list with:
#'   \item{data}{data.table with subclass and weight columns}
#'   \item{matchit}{a list with $weights and $subclass for back-compat}
gd_refine_matches <- function(dt_match, dt_full,
                              cutpoints,
                              uid, tid) {

  covariates <- names(cutpoints)

  ## build long-format match table
  dt_long <- gd_build_dt_long(dt_match, uid, tid)

  ## get unique person-years from the matched set
  dt_uq <- funique(dt_long[, .(uid, tid)])
  dt_coarse <- join(dt_uq, dt_full[, c(uid, tid, covariates), with = FALSE],
                     on = c("uid" = uid, "tid" = tid))


  ## compute breaks for each covariate
  l_breaks <- setNames(lapply(covariates, gd_extract_breaks,
                              cutpoints = cutpoints, dt_ref = dt_coarse),
                       covariates)

  ## coarsen all covariates in one shot
  l_coarse_cols <- paste0(".coarse_", covariates)
  dt_coarse[, (l_coarse_cols) := lapply(covariates, function(v) coarse_bin(get(v), breaks = l_breaks[[v]]))]

  ## merge coarse columns to the full dt_long
  coarse_cols <- c("uid", "tid", covariates, paste0(".coarse_", covariates))
  dt_long2 <- join(dt_long, dt_coarse[, ..coarse_cols], on = c("uid", "tid"))
    ## create cell key: set × coarsened covariates
  cell_cols <- c("set", paste0(".coarse_", covariates))
  dt_long2[, .cell := .GRP, by = cell_cols]

  ## dt_long[, .cell2 := collapse::finteraction(.SD, sep = "_"), .SD = cell_cols] # could save 0.1 secs for 6k trtd
  ## dt_long[, .(.cell, .cell2)]

  
  ## alternative approach: make coarse variable, add that to dt_long, then inner join
  ## dt_coarse[, coarse_cov := collapse::finteraction(.SD), .SDcols = c("tid", l_coarse_cols)] # uncl if tid is ok here
  ## dt_long3 <- join(dt_long, dt_coarse[, .(treated_id = uid, coarse_cov, tid)],  on = c("treated_id", "tid"))
  ## join(dt_long3, dt_coarse, on = "coarse_cov", how = "inner", multiple = F)
  ## idk if that works: people can be in multiple sets
  ## merging only on coarsed_cov variable doesn't consider whether treatment history is same

  
  ## count treated and control per cell
  dt_long2[, `:=`(.n_treat = sum(treat), N = .N), by = .cell][, .n_ctrl := N - .n_treat]

  
  ## doesn't really seem possible to get speed improvements here,
  ## collapse's (grouped) fsum doesn't seem faster than DTs
  ## dt_long2 <- dt_long %>% collapse::fgroup_by(.cell) %>%
  ##   collapse::fmutate(.n_treat = collapse::fsum(treat))
                      ## N        = collapse::fnobs(treat),
                      ## .n_ctrl  = N - .n_treat)

  ## join(dt_long[, .(.cell, tr1 = .n_treat, N1 = N, ctrl1 = .n_ctrl)],
  ##      dt_long2[, .(.cell, tr2 = .n_treat, N2 = N, ctrl2 = .n_ctrl)], on = ".cell") %>%
  ##   .[tr1 != tr2]

  ## assign subclass and weights
  ## subclass: only cells with both treated and control
  
  dt_long2[.n_treat > 0 & .n_ctrl > 0, subclass := .GRP, by = .cell]
  ## base ATT weights: treated=1, control=n_treat/n_ctrl (within subclass)
  dt_long2[treat == 1 & !is.na(subclass), weight := 1.0]
  dt_long2[treat == 0 & !is.na(subclass), weight := .n_treat / .n_ctrl]
  dt_long2[is.na(subclass), weight := 0]
  ## rescale so weights sum to group count within each treatment arm
  ## (matches matchit:::.make_sum_to_n)
  dt_long2[!is.na(subclass), weight := .N * weight / sum(weight), by = .(treat)]

  ## clean up temp columns
  dt_long2[, c(".n_treat", ".n_ctrl", ".cell", "N", paste0(".coarse_", covariates)) := NULL]

  ## rename internal uid/tid to caller's column names
  setnames(dt_long2, c("uid", "tid"), c(uid, tid))

  ## wrap results in mock matchit object for back-compat
  r_match <- list(weights = dt_long2$weight, subclass = dt_long2$subclass)
  class(r_match) <- "matchit"

  list(data = dt_long2, matchit = r_match)
}

#' Coarsen a numeric vector into bins. 
#'
#' @description
#' If `breaks` is provided, uses those breakpoints directly.
#' Otherwise computes N equal-width bins from the range of `x`.
#' Uses `cut(include.lowest = TRUE)` semantics to match MatchIt CEM.
#'
#' @param x Numeric vector.
#' @param nbins Number of bins (ignored if breaks is provided).
#' @param breaks Optional numeric vector of breakpoints.
#' @return Integer vector of bin assignments (1..nbins).
coarse_bin <- function(x, nbins = NULL, breaks = NULL) {
  if (!is.null(breaks)) {
    ## match matchit::cem_matchit behavior: wrap with -Inf/Inf, use findInterval
    findInterval(x, c(-Inf, sort(unique(breaks)), Inf))
  } else {
    rng <- range(x, na.rm = TRUE)
    if (diff(rng) == 0 || nbins <= 1) return(rep(1L, length(x)))
    as.integer(cut(x, breaks = seq(rng[1], rng[2], length.out = nbins + 1),
                   include.lowest = TRUE))
  }
}

#' Compute quantile breaks for one covariate (helper for gd_coarse_breaks).
#'
#' @param v Covariate name.
#' @param dt_ref Reference data.table.
#' @param cutpoints Named list mapping covariate names to number of bins.
#' @return Numeric vector of breakpoints.
gd_breaks_one <- function(v, dt_ref, cutpoints) {
  nbins <- cutpoints[[v]]
  if (is.null(nbins)) stop("gd_breaks_one: cutpoints must specify a value for ", v)
  x <- dt_ref[[v]]
  if (length(unique(x)) <= nbins) {
    sort(unique(x))
  } else {
    ## quantile(x, probs = seq(0, 1, length.out = nbins + 1), na.rm = TRUE)
    quantile(x, probs = seq(1/nbins, 1-(1/nbins), length.out = nbins -1 ), na.rm = TRUE)
  }
}




#' Compute quantile-based breakpoints for CEM coarsening.
#'
#' @description
#' Computes breakpoints from a reference dataset such that each bin
#' contains roughly the same number of observations. This avoids the
#' problem of equal-width bins where skewed variables (like exhibition
#' counts) concentrate most observations in a single bin.
#'
#' The breaks are computed from the reference dataset (typically the
#' full panel), not from the matched long data, so that each observation
#' contributes exactly once to the bin boundaries.
#'
#' @param dt_ref A data.table containing the reference covariates.
#' @param covariates Character vector of covariate names.
#' @param cutpoints Named list mapping covariate names to number of bins.
#' @return Named list mapping covariate names to numeric break vectors.
gd_coarse_breaks <- function(dt_ref, cutpoints) {
  covariates <- names(cutpoints)
  setNames(lapply(covariates, gd_breaks_one, dt_ref, cutpoints), covariates)
}

#' Refine matches using Coarsened Exact Matching (CEM) — MatchIt version.
#'
#' @description
#' Original implementation using MatchIt::matchit(method = "cem").
#' Kept for cross-validation against the data.table version.
#' Uses integer cutpoints (equal-width bins) to match matchit's native behavior.
#'
#' @inheritParams gd_refine_matches
#' @return A list with data and matchit slots (same structure as gd_refine_matches).
gd_refine_matches_matchit <- function(dt_match, dt_full,
                                      cutpoints,
                                      uid, tid) {
  ## browser()
  covariates <- names(cutpoints)

  ## build long-format match table (same as DT version)
  dt_long <- gd_build_dt_long(dt_match, uid, tid)

  ## merge covariates from full panel
  setnames(dt_long, c("uid", "tid"), c(uid, tid))
  dt_long <- join(dt_long, dt_full, on = c(uid, tid), verbose = FALSE)

  ## pass cutpoints through; matchit handles them internally:
  ##   integer → equal-width bins
  ##   vector  → findInterval(c(-Inf, sort(unique(breaks)), Inf))
  formula <- as.formula(paste("treat ~ set +", paste(covariates, collapse = " + ")))
  r_match <- matchit(formula, data = dt_long, method = "cem",
                     cutpoints = cutpoints)



  dt_long[, subclass := r_match$subclass]
  list(data = dt_long, matchit = r_match)
}

#' Check whether two CEM match results are equivalent.
#'
#' @description
#' Compares two match result objects (e.g. from gd_refine_matches and
#' gd_refine_matches_matchit) by checking that they retain the same set
#' of matched observations with the same weights.
#'
#' Checks performed:
#' 1. Same total number of rows
#' 2. Same number of matched (non-NA subclass) rows
#' 3. Matched (uid, tid, treat, set) tuples are identical (order-agnostic)
#' 4. Weights are identical (aligned by key)
#'
#' @param r1,r2 Match result objects (each a list with $data and $matchit).
#' @param uid String. Column name for the unit identifier.
#' @param tid String. Column name for the time identifier.
#' @return TRUE if the two match results are equivalent, FALSE otherwise.
gd_match_equivalent <- function(r1, r2, uid, tid) {
  ## 1. total row count
  if (nrow(r1$data) != nrow(r2$data)) return(FALSE)

  ## browser()

  ## extract matched indicators
  sc1 <- if (is.factor(r1$matchit$subclass)) as.integer(r1$matchit$subclass) else r1$matchit$subclass
  sc2 <- if (is.factor(r2$matchit$subclass)) as.integer(r2$matchit$subclass) else r2$matchit$subclass

  m1 <- !is.na(sc1)
  m2 <- !is.na(sc2)

  ## unique number of subclasses
  if (uniqueN(na.omit(sc1)) != uniqueN(na.omit(sc2))) return(FALSE)

  ## 2. same number of matched rows
  if (sum(m1) != sum(m2)) return(FALSE)
  if (sum(m1) == 0) return(TRUE)

  ## 3. matched (uid, tid, treat, set) tuples are identical
  key_cols <- c(uid, tid, "treat", "set")
  if (!fsetequal(r1$data[m1, ..key_cols],
                 r2$data[m2, ..key_cols])) return(FALSE)

  ## 4. weights match (aligned by key)
  dt_w1 <- r1$data[m1, ..key_cols][, w1 := as.numeric(r1$matchit$weights[m1])]
  dt_w2 <- r2$data[m2, ..key_cols][, w2 := as.numeric(r2$matchit$weights[m2])]
  dt_w <- join(dt_w1, dt_w2, on = key_cols, verbose = FALSE)
  if (nrow(dt_w) != sum(m1)) return(FALSE)
  if (!all(abs(dt_w$w1 - dt_w$w2) < 1e-10, na.rm = TRUE)) return(FALSE)

  TRUE
}

#' Run the full matching pipeline and return quality diagnostics.
#'
#' @description
#' Convenience wrapper running gd_match_history (matches-info mode)
#' then gd_refine_matches, then gd_quality_report. Use for parameter grid search.
#'
#' @param dt Panel data.table.
#' @param params Named list. Expected fields:
#'   L, treatment_col, history_col, uid, tid (passed to gd_match_history);
#'   covariates, cutpoints (passed to gd_refine_matches).
#' @param dt_full Full panel data for covariate merging in refinement.
#' @param sample_n_treated Optional integer. If set and the number of unique
#'   matched treated units exceeds this, a random sample is used for the CEM stage.
#' @return A single-row data.table of quality indicators.

gd_run_match_pipeline <- function(dt_panel, params, dt_full = dt_panel) {

  dt_match <- gd_match_history(
    dt_panel,
    L             = params$L,
    treatment_col = params$treatment_col,
    history_col   = params$history_col,
    uid           = params$uid,
    tid           = params$tid,
    tiers         = params$tiers, # %||% list(c("hist_str", "Nationality", "Gender"), c("hist_str")),
    return_type   = "matches-info"
  )

  if (nrow(dt_match) == 0) {
    warning("gd_run_match_pipeline: no matches found, returning NA quality row.")
    return(gd_quality_report(dt_panel, dt_match, matchit_obj = NULL,
                             refined_data = NULL, params = params))
  }

  ## subsample treated for CEM stage if requested (via params$sample_n_treated)
  dt_cem <- dt_match
  sample_n <- params$sample_n_treated
  if (!is.null(sample_n)) {
    treated_all <- funique(dt_match$treated_id)
    if (length(treated_all) > sample_n) {
      keep <- sample(treated_all, sample_n)
      dt_cem <- dt_match[.(keep), on = .(treated_id), nomatch = NULL]
    }
  }

  refined <- gd_refine_matches(dt_cem, dt_full,
                               cutpoints  = params$cutpoints,
                               uid        = params$uid,
                               tid        = params$tid)

  gd_quality_report(dt_panel, dt_match,
                    matchit_obj  = refined$matchit,
                    refined_data = refined$data,
                    params       = params)
}

#' Build a config grid from varying parameters.
#'
#' @description
#' Generates all combinations of the supplied parameters. All named
#' arguments are treated as alternatives (vectors/lists of values).
#' Arguments with length 1 are treated as single values, arguments
#' with length > 1 produce multiple configs.
#'
#' For list-valued parameters like covariates or cutpoints, wrap each
#' alternative in a list: e.g. `covariates = list(c("x"), c("y", "z"))`.
#' A single alternative: `covariates = list(c("x"))`.
#'
#' @param dt Panel data.table (constant across all configs).
#' @param ... Named arguments. Each is a vector/list of alternatives.
#' @return A list of config lists, one per parameter combination.
gd_build_configs <- function(dt_panel, ...) {
  ## CAUTION_OLD_FUNC

  l_args <- list(...)

  ## all params are alternatives — build indices for each
  l_indices <- lapply(l_args, function(x) seq_along(x))
  dt_grid <- do.call(data.table::CJ, c(l_indices, list(sorted = FALSE)))
  setnames(dt_grid, names(l_args))

  ## convert each grid row to a config
  l_configs <- apply(dt_grid, 1, function(row) {
    c(list(dt_panel = dt_panel),
      map(setNames(nm = names(l_args)), ~l_args[[.x]][[row[[.x]]]]))
  })

  l_configs
}

#' Run the pipeline across a config grid and collect results.
#'
#' @description
#' Iterates over configs from gd_build_configs (or a list of configs),
#' calls gd_run_match_pipeline for each, and collects the quality report
#' rows into a single data.table.
#'
#' @param l_configs A list of config lists (as from gd_build_configs).
#' @param dt_full Optional full panel data (default uses each config's dt).
#' @return data.table with one row per config, columns from quality report
#'   plus a `label` column for identification.
gd_run_configs <- function(l_configs, dt_full = NULL) {
  rbindlist(lapply(seq_along(l_configs), function(i) {
    cfg <- l_configs[[i]]
    label <- cfg$label %||% sprintf("cfg_%d", i)
    dt_use <- dt_full %||% cfg$dt_panel

    result <- tryCatch(
      gd_run_match_pipeline(cfg$dt_panel, cfg, dt_full = dt_use),
      error = function(e) {
        warning(sprintf("[%s] pipeline failed: %s", label, conditionMessage(e)))
        data.table(L = cfg$L, match_rate = NA_real_, n_matched = NA_integer_)
      }
    )

    if (is.data.table(result) && nrow(result) == 1) {
      result[, label := label]
    }
    result
  }), fill = TRUE)
}

#' Compute a flat single-row quality report for one parameter combination.
#'
#' @description
#' Extracts stage-1 (exact matching) and stage-2 (CEM) quality indicators into
#' a single data.table row. Designed so that many rows can be rbind-ed into a
#' comparison table when doing parameter grid search.
#'
#' Stage-1 indicators:
#'   n_treated, n_matched, match_rate, pct_tier1, pct_tier2,
#'   avg_controls_per_treated, min_controls_per_treated
#'
#' Stage-2 indicators:
#'   n_after_cem, cem_match_rate, L1_before, L1_after (multivariate L1),
#'   and per-covariate SMD and variance ratio before/after.
#'
#' @param dt_prepared data.table after md_prep_match() — used for n_treated denominator.
#' @param dt_match data.table from gd_match_history(matches-info).
#' @param matchit_obj The matchit object from gd_refine_matches()$matchit. NULL if no refinement.
#' @param refined_data The data slot from gd_refine_matches()$data.
#' @param params Named list of parameters used for this run.
#' @return Single-row data.table.
gd_quality_report <- function(dt_prepared, dt_match, matchit_obj = NULL,
                              refined_data = NULL, params = list()) {
  t1 <- Sys.time()
  ## stage 1: exact matching coverage
  dt_s1 <- gd_quality_report_s1(dt_prepared, dt_match, params)

  ## stage 2: CEM balance diagnostics
  dt_s2 <- gd_quality_report_s2(matchit_obj, refined_data, params)

  ## combine with params as leading columns
  dt_params <- if (length(params) > 0) {
    as.data.table(lapply(params, function(x) {
      if (length(x) > 1) paste(x, collapse = ",") else x
    }))
  } else data.table(stat = character(), cov = character(), tc = character(), stage = character(), val = numeric())

  t2 <- Sys.time()

  dt_time <- data.table(tdiff = difftime(t2, t1, units = "secs") %>% as.numeric)

  cbind(dt_params, dt_s1, dt_s2, dt_time)
}

#' @rdname gd_quality_report
#' Stage-1 helper: exact matching coverage from dt_match
gd_quality_report_s1 <- function(dt_prepared, dt_match, params) {
  ## count treated in the population
  n_treated <- if ("treat_bin" %in% names(dt_prepared)) {
    uniqueN(dt_prepared[treat_bin == 1, uid])
  } else {
    if (is.null(params$treatment_col)) stop("gd_quality_report_s1: params$treatment_col required")
    if (is.null(params$uid)) stop("gd_quality_report_s1: params$uid required")
    uniqueN(dt_prepared[get(params$treatment_col) > 0, get(params$uid)])
  }

  if (nrow(dt_match) == 0) {
    return(data.table(n_treated = n_treated, n_matched = 0L, match_rate = 0,
                      pct_tier1 = NA_real_, pct_tier2 = NA_real_,
                      avg_controls_per_treated = NA_real_,
                      min_controls_per_treated = NA_integer_))
  }

  matched_treated <- unique(dt_match$treated_id)
  n_matched <- length(matched_treated)

  ## tier breakdown: one tier assignment per treated unit
  tier_counts <- if ("match_tier" %in% names(dt_match)) {
    dt_match[, .(tier = match_tier[1]), by = treated_id]
  } else NULL

  pct_tier1 <- if (!is.null(tier_counts)) mean(tier_counts$tier == 1) else NA_real_
  pct_tier2 <- if (!is.null(tier_counts)) mean(tier_counts$tier == 2) else NA_real_

  ## controls-per-treated
  ctrl_counts <- dt_match[, .(n_ctrl = uniqueN(control_id)), by = treated_id]

  data.table(n_treated = n_treated, n_matched = n_matched,
             match_rate = round(n_matched / n_treated, 4),
             pct_tier1 = round(pct_tier1, 4), pct_tier2 = round(pct_tier2, 4),
             avg_controls_per_treated = round(mean(ctrl_counts$n_ctrl), 2),
             min_controls_per_treated = min(ctrl_counts$n_ctrl))
}

#' Build SMD/VR column block for one covariate (helper for gd_quality_report_s2).
#'
#' @param v Covariate name (string).
#' @param dt_smd data.table from gd_smd_vr with columns cov, smd_un, vr_un, smd_adj, vr_adj.
#' @return Single-row data.table with four columns: smd/vr before/after.
gd_bal_cols_cov <- function(v, dt_smd) {
  dt_row <- dt_smd[cov == v]
  if (nrow(dt_row) == 0) {
    setNames(data.table(NA_real_, NA_real_, NA_real_, NA_real_),
             c(paste0("smd_", v, "_before"), paste0("vr_", v, "_before"),
               paste0("smd_", v, "_after"),  paste0("vr_", v, "_after")))
  } else {
    setNames(data.table(round(dt_row$smd_un, 4), round(dt_row$vr_un, 4),
                         round(dt_row$smd_adj, 4), round(dt_row$vr_adj, 4)),
             c(paste0("smd_", v, "_before"), paste0("vr_", v, "_before"),
               paste0("smd_", v, "_after"),  paste0("vr_", v, "_after")))
  }
}

#' @rdname gd_quality_report
#' Stage-2 helper: CEM balance diagnostics from matchit object
gd_quality_report_s2 <- function(matchit_obj, refined_data, params) {
  if (is.null(matchit_obj) || is.null(refined_data)) {
    return(data.table(n_after_cem = NA_integer_, cem_match_rate = NA_real_,
                      L1_before = NA_real_, L1_after = NA_real_))
  }

  w_after <- matchit_obj$weights
  treat_v <- refined_data$treat

  ## n after CEM and match rate
  n_after_cem <- sum(treat_v == 1 & w_after > 0)
  n_treated_in_cem <- sum(treat_v == 1)
  cem_match_rate <- if (n_treated_in_cem > 0) {
    round(n_after_cem / n_treated_in_cem, 4)
  } else NA_real_

  ## identify real covariates (not the set dummies from matchit)
  covs <- intersect(names(params$cutpoints), names(refined_data))

  if (length(covs) == 0) {
    return(data.table(n_after_cem = as.integer(n_after_cem),
                      cem_match_rate = cem_match_rate,
                      L1_before = NA_real_, L1_after = NA_real_))
  }

  dt_cov <- refined_data[, ..covs]

  ## L1 imbalance
  l1_results <- gd_l1_med_both(dt_cov, treat_v, w_after,
                               l1.n = 51L, l1.max.bin = 7L)

  ## per-covariate SMD + variance ratio
  dt_smd <- gd_smd_vr(dt_cov, treat_v, w_after)

  ## build SMD/VR columns — one per covariate
  l_bal <- lapply(covs, gd_bal_cols_cov, dt_smd)

  data.table(n_after_cem = as.integer(n_after_cem),
             cem_match_rate = cem_match_rate,
             L1_before = round(l1_results$before, 4),
             L1_after  = round(l1_results$after, 4)) %>%
    cbind(do.call(cbind, l_bal))
}

#' Generate one random coarsening and compute its L1 statistic.
#'
#' @description
#' Draws random bin counts for each covariate, bins them, computes L1
#' under uniform weights using pre-computed .wt / .wc columns.
#' Returns nbins (not binned columns) to avoid 51x copy overhead.
#'
#' @param dt_loc data.table with .t (logical treat), .wt, .wc columns.
#' @param cov_names Character vector of covariate names.
#' @param ranges List of ranges (min/max) per covariate.
#' @param l1.min.bin Minimum number of bins per coarsening.
#' @param l1.max.bin Maximum number of bins per coarsening.
#' @param nu Integer vector of unique value counts per covariate.
#' @param cut_cols Character vector of column names to store bin assignments.
#' @return Named list with l1_u (numeric) and nbins (integer vector).
gd_gen_coarsening <- function(dt_loc, cov_names, ranges, l1.min.bin, l1.max.bin,
                              nu, cut_cols) {
  nbins <- vapply(seq_along(cov_names), function(i) {
    rng <- seq(min(l1.min.bin, nu[i]), min(l1.max.bin, nu[i]))
    rng[sample.int(length(rng), 1L)]
  }, integer(1))

  dt_loc[, (cut_cols) := lapply(seq_along(cov_names), function(i) {
    if (diff(ranges[[i]]) == 0) return(rep(1L, .N))
    as.integer(findInterval(get(cov_names[i]),
      seq(ranges[[i]][1], ranges[[i]][2], length.out = nbins[i] + 1),
      rightmost.closed = TRUE))
  })]

  dt_agg <- dt_loc[, .(wT = sum(.wt), wC = sum(.wc)), by = cut_cols]
  l1_u <- sum(abs(dt_agg$wT - dt_agg$wC)) / 2

  dt_loc[, (cut_cols) := NULL]

  list(l1_u = l1_u, nbins = nbins)
}


#' Fast multivariate L1 imbalance (before+after), matching cobalt methodology.
#'
#' Implements the exact same algorithm as cobalt::bal.compute(..., stat = "l1.med"):
#' 1. Generate `l1.n` random coarsenings (bin counts per covariate drawn uniformly
#'    from [l1.min.bin, l1.max.bin]).
#' 2. For each coarsening, bin covariates via equal-spaced cutpoints and compute
#'    L1 = sum over cells |weighted_share_treated - weighted_share_control| / 2
#'    /under uniform weights/.
#' 3. Select the coarsening with the median L1 value.
#' 4. Compute both unweighted (before) and CEM-weighted (after) L1 on that single
#'    fixed coarsening.
#'
#' This matches cobalt's methodology exactly (fixed median coarsening).
#' The all-numeric data.table-vectorized inner loop makes this ~5x faster than
#' cobalt, scaling to >10M rows in a few seconds.
#'
#' @param dt_cov data.frame or data.table of numeric covariates.
#' @param treat 0/1 or logical vector, length == nrow(dt_cov).
#' @param weights_after Weight vector for the "after" (matched) state.
#' @param l1.n Number of random coarsenings to generate (default 51).
#' @param l1.min.bin Min number of bins per covariate per coarsening (default 2).
#' @param l1.max.bin Max number of bins per covariate per coarsening (default 12).
#' @param seed Optional RNG seed for reproducibility.
#' @return Named list with `before` and `after` entries (each numeric in [0,1]).
gd_l1_med_both <- function(dt_cov, treat, weights_after,
                           l1.n = 51L, l1.min.bin = 2L, l1.max.bin = 12L,
                           seed = NULL) {
  if (!is.null(seed)) set.seed(seed)

  dt_loc <- as.data.table(dt_cov)
  cov_names <- copy(names(dt_loc))
  n <- length(treat)
  is_t <- as.logical(treat)

  ## uniform weights for finding median coarsening (step 2)
  w_u <- rep(1, n)
  w_u[is_t] <- w_u[is_t] / sum(w_u[is_t])
  w_u[!is_t] <- w_u[!is_t] / sum(w_u[!is_t])

  dt_loc[, `:=`(.t = is_t, .w_u = w_u, .wt = w_u * is_t, .wc = w_u * !is_t)]

  ranges <- lapply(cov_names, function(c) range(dt_loc[[c]], na.rm = TRUE))
  nu <- vapply(cov_names, function(c) uniqueN(dt_loc[[c]]), integer(1))
  cut_cols <- paste0(".b_", cov_names)

  ## step 1-2: generate l1.n coarsenings (returns nbins, not bin_df)
  l1_results <- lapply(seq_len(l1.n), function(k) {
    gd_gen_coarsening(dt_loc, cov_names, ranges, l1.min.bin, l1.max.bin, nu, cut_cols)
  })

  l1s_u <- sapply(l1_results, `[[`, "l1_u")
  l_nbins <- lapply(l1_results, `[[`, "nbins")

  ## step 3: pick median coarsening, rebuild bins once
  median_idx <- which(l1s_u == sort(l1s_u, partial = ceiling(l1.n / 2))[ceiling(l1.n / 2)])[1]
  nbins_fixed <- l_nbins[[median_idx]]
  b_cols <- paste0(".b_", cov_names)
  dt_loc[, (b_cols) := lapply(seq_along(cov_names), function(i) {
    as.integer(findInterval(dt_loc[[cov_names[i]]],
      seq(ranges[[i]][1], ranges[[i]][2], length.out = nbins_fixed[i] + 1),
      rightmost.closed = TRUE))
  })]
  dt_fixed_cuts <- dt_loc[, ..b_cols]
  dt_loc[, (b_cols) := NULL]

  ## step 4: compute before (uniform) and after (weighted) on fixed coarsening
  dt_fixed_cuts[, bin_id := do.call(paste, c(.SD, sep = "_"))]
  w_o <- weights_after
  w_o[is_t] <- w_o[is_t] / sum(w_o[is_t])
  w_o[!is_t] <- w_o[!is_t] / sum(w_o[!is_t])

  dt_fixed <- data.table(bin = dt_fixed_cuts$bin_id,
                         .wu = w_u, .wo = w_o, .t = is_t)
  dt_agg_before <- dt_fixed[, .(wT = sum(.wu * .t), wC = sum(.wu * !.t)), by = bin]
  dt_agg_after  <- dt_fixed[, .(wT = sum(.wo * .t), wC = sum(.wo * !.t)), by = bin]

  list(before = sum(abs(dt_agg_before$wT - dt_agg_before$wC)) / 2,
       after  = sum(abs(dt_agg_after$wT  - dt_agg_after$wC))  / 2)
}


#' Fast multivariate L1 imbalance — single-weight wrapper.
#'
#' Wrapper around gd_l1_med_both for backward compatibility.
#' Returns the entry matching the weight type (before/unweighted or after/weighted).
#'
#' @inheritParams gd_l1_med_both
#' @param weights non-negative weight vector. Use rep(1, n) for unmatched baseline.
#' @return Numeric scalar in [0, 1].
gd_l1_med <- function(dt_cov, treat, weights,
                      l1.n = 101L, l1.min.bin = 2L, l1.max.bin = 12L,
                      seed = NULL) {
  both <- gd_l1_med_both(dt_cov, treat, weights, l1.n, l1.min.bin, l1.max.bin, seed)
  if (isTRUE(all(weights == 1))) both[["before"]] else both[["after"]]
}


#' Compute SMD and variance ratio for a single covariate.
#'
#' @description
#' Computes unweighted and CEM-weighted standardized mean difference and
#' variance ratio for one covariate. Matches cobalt defaults:
#' s.d.denom = "pooled" (unweighted pooled SD).
#'
#' @param cn Covariate name (string).
#' @param dt_smd data.table with .treat (logical) and .w (weights) columns.
#' @return Named list: cn, smd_un, vr_un, smd_adj, vr_adj.
gd_smd_vr_cov <- function(cn, dt_smd) {
  vT <- dt_smd[.treat == TRUE,  get(cn)]
  vC <- dt_smd[.treat == FALSE, get(cn)]

  ## unweighted (before)
  mT_u <- mean(vT)
  mC_u <- mean(vC)
  vT_u <- var(vT)
  vC_u <- var(vC)
  sd_p <- sqrt((vT_u + vC_u) / 2)

  ## weighted (after) per cobalt formula:
  ## weighted variance = sum(w_norm * (x - mean)^2) / (1 - sum(w_norm^2))
  wT <- dt_smd[.treat == TRUE,  .w]
  wC <- dt_smd[.treat == FALSE, .w]
  wTn <- wT / sum(wT)
  wCn <- wC / sum(wC)

  mT_w <- sum(wTn * vT)
  mC_w <- sum(wCn * vC)

  vT_w <- sum(wTn * (vT - mT_w)^2) / (1 - sum(wTn^2))
  vC_w <- sum(wCn * (vC - mC_w)^2) / (1 - sum(wCn^2))

  list(cn,
       smd_un = (mT_u - mC_u) / sd_p,
       vr_un  = vT_u / vC_u,
       smd_adj = (mT_w - mC_w) / sd_p,
       vr_adj  = vT_w / vC_w)
}

#' Fast per-covariate SMD + variance ratio (~17x faster than cobalt::bal.tab).
#'
#' @param dt_cov data.frame or data.table of numeric covariates.
#' @param treat 0/1 or logical vector, length == nrow(dt_cov).
#' @param weights non-negative weight vector (CEM weights).
#' @return data.table with columns: cov, smd_un, vr_un, smd_adj, vr_adj.
gd_smd_vr <- function(dt_cov, treat, weights) {
  dt_d <- as.data.table(dt_cov)
  cov_names <- copy(names(dt_d))
  dt_d[, `:=`(.treat = as.logical(treat), .w = weights)]

  ## compute SMD and VR for each covariate via named helper
  out <- lapply(cov_names, gd_smd_vr_cov, dt_d)

  rbindlist(out) %>%
    setnames(c("cov", "smd_un", "vr_un", "smd_adj", "vr_adj"))
}

#' Fast eCDF (max and mean) for one covariate.
#'
#' Computes the Kolmogorov-Smirnov statistic (max eCDF difference) and
#' mean eCDF difference between treated and control groups.
#'
#' @param x Numeric vector of covariate values.
#' @param treat Logical or 0/1 vector of treatment indicators.
#' @param w Numeric vector of weights (NULL = uniform).
#' @return Named numeric: ecdf_max, ecdf_mean.
gd_ecdf_one <- function(x, treat, w = NULL) {
  #' compute eCDF max (KS) and mean for one covariate
  #' evaluates at unique x values (handles ties correctly)
  n <- length(x)
  if (is.null(w)) w <- rep(1, n)
  ord <- order(x)
  w_t <- sum(w[treat == 1])
  w_c <- sum(w[treat == 0])

  ## cumulative sums at each observation in sorted order
  cum_w_t <- base::cumsum(w[ord] * treat[ord]) / w_t
  cum_w_c <- base::cumsum(w[ord] * (1 - treat[ord])) / w_c

  ## evaluate only at last occurrence of each unique x value
  ## (handles ties: all tied obs contribute simultaneously)
  last_idx <- !duplicated(x[ord], fromLast = TRUE)
  diff <- abs(cum_w_t[last_idx] - cum_w_c[last_idx])

  c(ecdf_max = max(diff), ecdf_mean = mean(diff))
}

#' Fast eCDF statistics for multiple covariates.
#'
#' Computes unweighted and weighted eCDF max (KS) and eCDF mean for
#' each covariate in a data.table. Mirrors the gd_smd_vr interface.
#'
#' @inheritParams gd_smd_vr
#' @return data.table with columns: cov, ecdf_max_un, ecdf_mean_un,
#'   ecdf_max_adj, ecdf_mean_adj.
gd_ecdf <- function(dt_cov, treat, weights) {
  dt_d <- as.data.table(dt_cov)
  cov_names <- copy(names(dt_d))
  is_t <- as.logical(treat)

  rbindlist(lapply(cov_names, function(v) {
    x <- dt_d[[v]]
    un <- gd_ecdf_one(x, is_t, NULL)
    adj <- gd_ecdf_one(x, is_t, weights)
    data.table(cov = v,
               ecdf_max_un = un["ecdf_max"], ecdf_mean_un = un["ecdf_mean"],
               ecdf_max_adj = adj["ecdf_max"], ecdf_mean_adj = adj["ecdf_mean"])
  }))
}

# =============================================================================
# Multicategory CEM Stratum Construction
# =============================================================================
# The following functions implement the CEM stratum approach for multicategory
# treatments (Iacus, King, Porro 2012, Section 5.1). Instead of the two-stage
# (exact-match -> CEM-refine) pipeline for binary treatment, we:
#   1. Coarsen cumulative treatment history for each institution type
#   2. Create L lags of each coarsened history
#   3. Form strata from (year, multivariate hist_str, coarsened covariates)
#   4. Keep all strata (feols handles within-stratum collinearity)
#
# This approach:
#   - Handles multiple treatment types simultaneously
#   - Ensures matched units share identical histories across ALL treatment types
#   - Is dramatically simpler computationally (no Cartesian joins, no sets)
#   - Reuses existing coarsening/diagnostic infrastructure (coarse_bin,
#     gd_coarse_breaks, gd_l1_med_both, gd_smd_vr)

#' Compute quantile breakpoints for one history column.
#'
#' @param dt_ref Reference data.table containing the full panel.
#' @param hcol String. Column name in `dt_ref` for which to compute breaks.
#' @param nb Integer. Number of bins (will be reduced if unique values < nb).
#' @return Numeric vector of breakpoints.
gd_hist_breaks_one <- function(dt_ref, hcol, nb) {
  x <- dt_ref[[hcol]]
  if (uniqueN(x, na.rm = TRUE) <= nb) sort(unique(x))
  ## else quantile(x, probs = seq(0, 1, length.out = nb + 1), na.rm = TRUE)
  else quantile(x, probs = seq(1/nb, 1-(1/nb), length.out = nb -1), na.rm = TRUE)
}

#' Coarsen cumulative history columns, returning a copy of `dt_d`.
#'
#' @param dt_d data.table containing `history_cols`.
#' @param dt_ref Reference data.table for computing quantile breaks.
#' @param history_cols Character vector. Names of cumulative history columns.
#' @param coarse_cols Character vector. Names for the resulting coarsened columns.
#' @param nb_vec Integer vector. Number of bins per history column.
#' @param history_breaks String. One of "quantile", "equal", or "none".
#' @return data.table with coarsened history columns appended.
gd_coarse_history <- function(dt_d, dt_ref, history_cols, coarse_cols,
                              nb_vec, history_breaks) {
  dt_coarse_hist <- copy(dt_d)
  
  dt_coarse_hist <- switch(history_breaks,
    none = dt_coarse_hist[, (coarse_cols) := lapply(history_cols, function(h) dt_coarse_hist[[h]])],
    quantile = {
      l_breaks <- setNames(map2(history_cols, nb_vec, ~gd_hist_breaks_one(dt_ref, .x, .y)),
                           coarse_cols)
      dt_coarse_hist[, (coarse_cols) := map2(history_cols, l_breaks[coarse_cols],
                                    ~coarse_bin(get(.x), breaks = .y))]
    },
    equal = dt_coarse_hist[, (coarse_cols) := map2(history_cols, nb_vec,
                                          ~coarse_bin(get(.x), nbins = .y))]
    )

  return(dt_coarse_hist)
  
}


#' Prepare multivariate treatment history for CEM stratum construction.
#'
#' @description
#' For each history column (cumulative exhibition counts), optionally coarsens
#' the values into bins, creates L lags of the coarsened values, then
#' concatenates all lagged values into a single multivariate `hist_str`.
#' This ensures that units in the same stratum share identical treatment
#' histories across all institution types.
#'
#' The coarsening step is critical: without it, artists with 200 vs 201 prior
#' PI exhibitions would be in different strata despite being substantively
#' identical. Coarsening bins these together.
#'
#' Coarsening can be:
#'   - "quantile": quantile-based breaks from the full panel (default)
#'   - "equal": equal-width bins via coarse_bin
#'   - "none": no coarsening (raw cumulative values used as-is)
#'
#' @param dt_panel data.table. Panel data with cumulative history columns.
#' @param L Integer. Number of lags to construct.
#' @param history_cols Character vector. Names of cumulative history columns.
#'   These should represent state at the START of each year (cumulative counts
#'   up to that point).
#' @param history_nbins Integer or named integer vector. Number of bins per
#'   history column. If a single integer, applied to all columns. Ignored if
#'   `history_breaks = "none"`.
#' @param history_breaks String. One of "quantile", "equal", or "none".
#' @param uid String. Unit identifier column name in dt_panel.
#' @param tid String. Time identifier column name in dt_panel.
#' @param dt_ref Optional reference data.table for computing quantile breaks.
#'   Defaults to dt_panel.
#' @return data.table with internal uid/tid columns, lag columns for each
#'   coarsened history, and a multivariate hist_str column.
gd_prep_multivar_hist <- function(dt_panel, L, history_cols, history_nbins,
                                   history_breaks = "quantile",
                                  uid, tid, dt_ref = NULL) {

  dt_d <- copy(dt_panel)
  setnames(dt_d, c(uid, tid), c("uid", "tid"))
  dt_d <- dt_d[order(uid, tid)]

  if (is.null(dt_ref)) dt_ref <- dt_d

  ## short internal names for lag columns
  hist_tags <- paste0("h", seq_along(history_cols))
  coarse_cols <- paste0(hist_tags, "_c")

  ## coarsen cumulative values (before lagging)
  nb_vec <- if (length(history_nbins) == 1L) rep(history_nbins, length(history_cols)) else history_nbins

  dt_coarse_hist <- gd_coarse_history(dt_d, dt_ref, history_cols, coarse_cols, nb_vec, history_breaks)

  
  ## create L lags of each coarsened history column
  dt_lags <- collapse::L(dt_coarse_hist, by = ~uid, n = 0:(L - 1), cols = coarse_cols)
  all_lag_cols <- setdiff(names(dt_lags), "uid")
  
  dt_d2 <- cbind(dt_d, dt_lags[, ..all_lag_cols])


  ## filter to complete cases and create multivariate hist_str
  dt_d2 <- collapse::na_omit(dt_d2, cols = all_lag_cols)
  dt_d2[, hist_str := collapse::finteraction(.SD, sep = "_"), .SDcols = all_lag_cols]

  return(dt_d2)
}


#' @section Weight Functions:
#' The following functions compute observation weights for CEM strata.
#' They are called by \code{gd_cem_weights} dispatcher, which is invoked
#' inside \code{gd_cem_strata} when \code{weight_type} is specified in config.

#' CEM weights: uniform (no weighting).
#'
#' @param dt_d data.table. CEM-prepared data (ignored).
#' @return Numeric vector of ones.
gd_cem_weights_none <- function(dt_d) rep(1, nrow(dt_d))

#' CEM weights: any-treatment vs pure control.
#'
#' Collapses all treatment columns into "any treatment" vs "pure control"
#' (all treatments = 0), then computes standard CEM ATT weights per stratum:
#' treated = 1, control = (mC / mT) * (msT / msC).
#'
#' @param dt_d data.table with stratum and treatment columns.
#' @param treat_cols Character vector of binary treatment column names.
#' @return Numeric vector of weights.
gd_cem_weights_any_ctrl <- function(dt_d, treat_cols) {
  any_treat <- as.integer(Reduce(`|`, lapply(dt_d[, ..treat_cols], `>`, 0)))
    
  mT <- sum(any_treat)
  mC <- length(any_treat) - mT
  dt_d[, .any_treat := any_treat]
  w <- dt_d[, {
    msT <- sum(.any_treat)
    msC <- .N - msT
    if (msT > 0 & msC > 0) fifelse(.any_treat == 1, 1, (mC / mT) * (msT / msC)) else rep_len(0, .N)
  }, by = stratum]$V1
  dt_d[, .any_treat := NULL]
  w

  ## data.table(w=w)[w < 5] %>% ggplot(aes(x=w)) + geom_density()
}

#' CEM weights: composite treatment factor.
#'
#' Creates a single factor from all treatment column patterns, then computes
#' CEM ATT weights per stratum relative to the pure control baseline.
#' Each non-control pattern gets weight = (mC / mP) * (msP / msC) where
#' mC/mP are global counts of control/pattern and msP/msC are stratum counts.
#'
#' @inheritParams gd_cem_weights_any_ctrl
#' @return Numeric vector of weights.
gd_cem_weights_composite <- function(dt_d, treat_cols) {
  dt_d[, .treat_cat := collapse::finteraction(.SD, sep = "_"),
       .SDcols = treat_cols]
  ctrl_level <- paste(rep(0, length(treat_cols)), collapse = "_")

  ## global pattern counts
  dt_global <- dt_d[, .N, by = .treat_cat]
  names(dt_global)[2] <- "gN"
  mC <- dt_global[.treat_cat == ctrl_level, gN]

  ## per-stratum pattern counts
  dt_w <- dt_d[, .N, by = .(stratum, .treat_cat)]
  dt_w <- merge(dt_w, dt_global, by = ".treat_cat")

  ## compute weights per stratum
  dt_w[stratum %in% dt_w[, .(msC = sum(N[.treat_cat == ctrl_level])), by = stratum][msC > 0, stratum],
       w := fifelse(.treat_cat == ctrl_level, 1, (mC / gN) * (N / sum(N[.treat_cat == ctrl_level]))),
       by = stratum]

  ## merge back
  dt_w <- dt_w[, .(stratum, .treat_cat, w)]
  dt_d[dt_w, on = .(stratum, .treat_cat), w := i.w]
  w <- dt_d$w
  w[is.na(w)] <- 0
  dt_d[, c(".treat_cat", "w") := NULL]
  w

  ## dt_d[w<10] %>% ggplot(aes(x=w)) + geom_density()
}

#' CEM weights: quadratic programming (NOT IMPLEMENTED).
#'
#' Placeholder for future QP-based weights that simultaneously satisfy
#' ratio constraints for all treatment columns within each stratum.
#'
#' @inheritParams gd_cem_weights_any_ctrl
#' @return Never returns — raises error.
gd_cem_weights_qp <- function(dt_d, treat_cols) {
  stop("gd_cem_weights_qp: QP weights not yet implemented. ",
       "Use 'none', 'any_vs_ctrl', or 'composite'.", call. = FALSE)
}

#' CEM weight dispatcher.
#'
#' @param dt_d data.table. CEM-prepared data with stratum column.
#' @param treat_cols Character vector of treatment column names.
#' @param weight_type String. One of "none", "any_vs_ctrl", "composite", "qp".
#' @return Numeric vector of weights, length = nrow(dt_d).
gd_cem_weights <- function(dt_d, treat_cols, weight_type) {
  switch(weight_type,
    none        = gd_cem_weights_none(dt_d),
    any_vs_ctrl = gd_cem_weights_any_ctrl(dt_d, treat_cols),
    composite   = gd_cem_weights_composite(dt_d, treat_cols),
    qp          = gd_cem_weights_qp(dt_d, treat_cols),
    stop("gd_cem_weights: unknown weight_type '", weight_type,
         "'. Options: none, any_vs_ctrl, composite, qp.", call. = FALSE))
}

#' Form CEM strata for multicategory treatment analysis.
#'
#' @description
#' Full pipeline: prepare multivariate treatment history, coarsen covariates,
#' and form strata. Each stratum is a combination of:
#'   (year tid, multivariate hist_str, coarsened covariate bins)
#'
#' Within each stratum, all units share identical:
#'   - Treatment history across all institution types (L lags)
#'   - Coarsened covariate values
#'   - Year
#'
#' The resulting data can be passed directly to feols() for DiD estimation
#' with stratum fixed effects:
#'   feols(outcome ~ treat_PM + treat_PES + treat_gallery | stratum, data)
#'
#' If config$weight_type is set (one of "none", "any_vs_ctrl", "composite",
#' "qp"), CEM weights are computed and attached as a "weight" column.
#'
#' @param config Named list with the following fields:
#'   \itemize{
#'     \item dt_panel: data.table with panel data
#'     \item L: integer, number of lags
#'     \item treatment_cols: character vector of treatment column names
#'     \item history_cols: character vector of cumulative history column names
#'     \item history_nbins: integer or named vector, bins per history column
#'     \item history_breaks: string, "quantile", "equal", or "none"
#'     \item uid: string, unit identifier column
#'     \item tid: string, time identifier column
#'     \item covariate_cutpoints: named list of cutpoints for covariates (optional;
#'       covariate names are derived from names(cutpoints))
#'     \item weight_type: string, one of "none", "any_vs_ctrl", "composite",
#'       "qp" (optional, default "none")
#'   }
#' @return Named list:
#'   \item{data}{data.table with original columns plus stratum, hist_str, and
#'     coarsened covariate columns}
#'   \item{strata_summary}{data.table with one row per stratum (n_total,
#'     per-treatment counts, n_control)}
#'   \item{config}{the input config (for reference)}
gd_cem_strata <- function(config) {

  ## unpack config
  dt_panel           <- config$dt_panel
  L                  <- config$L
  treatment_cols     <- config$treatment_cols
  history_cols       <- config$history_cols
  history_nbins      <- config$history_nbins %||% 5L
  history_breaks     <- config$history_breaks %||% "quantile"
  uid                <- config$uid
  tid                <- config$tid
  covariate_cutpoints <- config$covariate_cutpoints %||% list()
  covariate_cols       <- names(covariate_cutpoints)
  weight_type        <- config$weight_type %||% "none"

  ## step 1: multivariate history preparation
  ## history columns: get lagged to construct hist_str
  ## covariates: don't get lagged
  dt_prep <- gd_prep_multivar_hist(
    dt_panel  = dt_panel,
    L         = L,
    history_cols   = history_cols,
    history_nbins  = history_nbins,
    history_breaks = history_breaks,
    uid       = uid,
    tid       = tid
  )

  ## step 2: coarsen covariates (reuse existing infrastructure)
  coarse_cov_cols <- character(0)
  if (length(covariate_cols) > 0 && length(covariate_cutpoints) > 0) {
    l_breaks <- gd_coarse_breaks(dt_prep, covariate_cutpoints)
    coarse_cov_cols <- paste0(".cr_", covariate_cols)
    dt_prep[, (coarse_cov_cols) := map(covariate_cols, ~coarse_bin(get(.x), breaks = l_breaks[[.x]]))]
  }

  ## step 3: form strata from year + hist_str + coarse covariates
  stratum_cols <- c("tid", "hist_str", coarse_cov_cols)
  dt_prep[, stratum := collapse::finteraction(.SD, sep = "_"), .SDcols = stratum_cols]

  ## step 4: build strata summary — total N, per-treatment counts, n_control
  dt_summary <- dt_prep[, c(
    list(n_total = .N),
    setNames(lapply(treatment_cols, function(tc) sum(get(tc) > 0)),
             paste0("n_", treatment_cols)),
    list(n_control = sum(Reduce(`&`, lapply(.SD, `<=`, 0)))) # for how many people are all treat cols 0
  ), by = stratum, .SDcols = treatment_cols]

  ## step 5: compute CEM weights
  dt_prep[, weight := gd_cem_weights(dt_prep, treatment_cols, weight_type)]

  ## step 6: restore original column names
  setnames(dt_prep, c("uid", "tid"), c(uid, tid))

  list(
    data           = dt_prep,
    strata_summary = dt_summary,
    config         = config
  )
}


#' Compute coverage stats for one treatment column (helper).
#'
#' @param tc String. Treatment column name.
#' @param dt_s data.table. Strata summary from gd_cem_strata.
#' @return Named numeric vector with n_strata_{tc}, pct_strata_{tc},
#'   and strata_{tc}_{min,median,mean,max}.
gd_cem_quality_treat_cov <- function(tc, dt_s) {
  n_treat <- dt_s[[paste0("n_", tc)]]
  n_treat_pos <- n_treat[n_treat > 0]
  n <- length(n_treat_pos)
  c(
    setNames(n, paste0("n_strata_", tc)),
    setNames(round(n / nrow(dt_s), 4), paste0("pct_strata_", tc)),
    if (n > 0) {
      setNames(c(min(n_treat_pos), as.integer(median(n_treat_pos)),
                  round(mean(n_treat_pos), 1), max(n_treat_pos)),
               paste0("strata_", tc, c("_min", "_median", "_mean", "_max")))
    } else {
      setNames(rep(NA_integer_, 4), paste0("strata_", tc, c("_min", "_median", "_mean", "_max")))
    }
  )
}




#' Balance diagnostics for one treatment contrast (helper).
#'
#' Computes SMD, VR, and L1 before and after weighting for a single
#' treatment column. "Before" = full data, uniform weights, k=1 vs k=0.
#' "After" = same data with unified CEM weights.
#' Prunes to strata where both k=1 and k=0 exist for the after comparison.
#' 
#' Returns a long data.table with columns: variable, measure, treatment, stage, value.
#' For L1, variable is "cov"/"hist"/"all"; for per-variable metrics it's the column name.
#' When \code{b_full = FALSE}, only SMD is computed (skips VR, eCDF, L1) — this is
#' substantially faster and sufficient for trend diagnostics.
#'
#' @param dt_d data.table containing balance variables.
#' @param all_cols Character vector. All variable names for per-variable SMD/VR/eCDF.
#' @param cov_cols Character vector. Covariate column names (for L1_cov).
#' @param hist_cols Character vector. History column names (for L1_hist).
#' @param treat_v Integer treatment vector (0/1).
#' @param weights Numeric weight vector.
#' @param tc String. Treatment column name.
#' @param stage String. "before" or "after".
#' @param b_full Logical. If TRUE (default), compute all metrics (SMD, VR, eCDF,
#'   L1). If FALSE, compute SMD only — skips the expensive L1 random coarsenings.
#' @return Long data.table with columns (variable, measure, treatment, stage, value).
gd_bal_stage <- function(dt_d, all_cols, cov_cols, hist_cols,
                          treat_v, weights, tc, stage, b_full = TRUE) {

  dt_all <- if (length(all_cols) > 0) dt_d[, ..all_cols] else data.table()

  if (length(all_cols) == 0) {
    return(data.table(variable = character(), measure = character(),
                       treatment = character(), stage = character(),
                       value = numeric()))
  }

  ## suffix for gd_smd_vr / gd_ecdf output: "un" for before, "adj" for after
  sfx <- if (stage == "before") "un" else "adj"

  ## per-variable SMD (always computed)
  dt_smd <- gd_smd_vr(dt_all, treat_v, weights)
  ## prep return object if b_full == F
  dt_out_smd <- melt(dt_smd[, .(cov, smd = get(paste0("smd_", sfx)))],
                      id.vars = "cov", variable.name = "measure",
                      value.name = "value") %>%
    setnames("cov", "variable")

  ## optional: VR, eCDF, L1 (expensive — skip when b_full = FALSE)
  if (!b_full) {
    return(dt_out_smd[, `:=`(treatment = tc, stage = stage)][,
      .(variable, measure, treatment, stage, value)])
  }

  dt_smd_full <- melt(dt_smd[, .(cov, vr = get(paste0("vr_", sfx)))],
                       id.vars = "cov", variable.name = "measure",
                       value.name = "value") %>%
    setnames("cov", "variable")
  dt_out_smd <- rbind(dt_out_smd, dt_smd_full)

  ## per-variable eCDF
  dt_ecdf <- gd_ecdf(dt_all, treat_v, weights)
  dt_out_ecdf <- melt(dt_ecdf[, .(cov, ecdf_max = get(paste0("ecdf_max_", sfx)),
                                   ecdf_mean = get(paste0("ecdf_mean_", sfx)))],
                       id.vars = "cov", variable.name = "measure",
                       value.name = "value") %>%
    setnames("cov", "variable")

  ## L1 variants — always include all three, NA if no columns
  dt_l1 <- data.table(
    variable = c("cov", "hist", "all"),
    measure = "L1",
    value = c(if (length(cov_cols) > 0) gd_l1_med_both(dt_d[, ..cov_cols], treat_v, weights)[[stage]] else NA_real_,
              if (length(hist_cols) > 0) gd_l1_med_both(dt_d[, ..hist_cols], treat_v, weights)[[stage]] else NA_real_,
              gd_l1_med_both(dt_all, treat_v, weights)[[stage]])
  )

  rbind(dt_out_smd, dt_out_ecdf, dt_l1, fill = F) %>%
    .[, `:=`(treatment = tc, stage = stage)] %>%
    .[, .(variable, measure, treatment, stage, value)]

}


#' Skeleton balance data.table for "no viable strata" case.
#'
#' @inheritParams gd_bal_stage
#' @return Long data.table with all values NA.
gd_bal_stage_nas <- function(all_cols, cov_cols, hist_cols, tc, stage) {
  per_var <- CJ(variable = all_cols, measure = c("smd", "vr", "ecdf_max", "ecdf_mean"))
  l1 <- data.table(variable = c("cov", "hist", "all"), measure = "L1")
  rbind(per_var, l1, fill = TRUE) %>%
    .[, `:=`(treatment = tc, stage = stage, value = NA_real_)] %>%
    .[, .(variable, measure, treatment, stage, value)]
}

#' Balance diagnostics for one treatment contrast (helper).
#'
#' Computes SMD, VR, and L1 before and after weighting for a single
#' treatment column. "Before" = full data, uniform weights, k=1 vs k=0.
#' "After" = same data with unified CEM weights.
#' Prunes to strata where both k=1 and k=0 exist for the after comparison.
#'
#' Returns NULL (skipped) if no covariates are specified.
#'
#' @param tc String. Treatment column name.
#' @param dt_d data.table. CEM-prepared data (from gd_cem_strata).
#' @param covariate_cols Character vector of covariate names.
#' @param history_cols Character vector of treatment history cols
#' @param stratum_col String. Column name of stratum assignment.
#' @return data.table with L1_{tc}_before/after and per-covariate
#'   smd/vr_{v}_{tc}_before/after, or NULL if no covariates.
gd_cem_quality_treat_bal <- function(tc, dt_d, covariate_cols, history_cols, stratum_col) {

  all_balance_cols <- c(covariate_cols, history_cols)
  if (length(all_balance_cols) == 0) return(data.table())

  treat_v <- as.integer(dt_d[[tc]] > 0)

  ## before: full data, uniform weights
  dt_before <- gd_bal_stage(dt_d, all_balance_cols, covariate_cols, history_cols,
                             treat_v, rep(1, nrow(dt_d)), tc, "before")

  ## after: prune to strata with both k=1 and k=0, ATT weights
  dt_strat <- dt_d[, .(n1 = sum(get(tc) > 0), n0 = sum(get(tc) == 0)),
                    by = stratum_col]
  viable_strata <- dt_strat[n1 > 0 & n0 > 0, get(stratum_col)]
  after_idx <- dt_d[[stratum_col]] %in% viable_strata

  dt_after <- if (sum(after_idx) == 0) {
    gd_bal_stage_nas(all_balance_cols, covariate_cols, history_cols, tc, "after")
  } else {
    dt_att <- dt_d[after_idx]
    dt_sz <- dt_att[, .(n1 = sum(get(tc) > 0), n0 = sum(get(tc) == 0)), by = stratum_col]
    mT <- sum(dt_sz$n1); mC <- sum(dt_sz$n0)
    dt_att[dt_sz, on = stratum_col, `:=`(.n1 = i.n1, .n0 = i.n0)]
    w <- dt_att[, fifelse(treat_v[after_idx] == 1, 1, (mC / mT) * (.n1 / .n0))]
    gd_bal_stage(dt_att, all_balance_cols, covariate_cols, history_cols,
                 treat_v[after_idx], w, tc, "after")
  }

  rbind(dt_before, dt_after)
}


#' Generate single-row CEM quality report.
#'
#' @description
#' Collects coverage, balance, and covariate diagnostics from a CEM stratum
#' run into a single-row data.table. Designed for rbindlist-ing across configs.
#'
#' Balance assessment follows cobalt's multi-category approach: for each
#' treatment column, compute SMD, VR, and L1 comparing that treatment vs its
#' complement, then report per-treatment and worst-case across treatments.
#'
#' @param cem_result List returned by gd_cem_strata.
#' @return A single-row data.table with columns:
#'   \itemize{
#'     \item L, history_breaks, history_nbins_str (config)
#'     \item n_prepped, n_strata, strata_median_size, strata_mean_size,
#'           strata_min_size, strata_max_size, n_hist_str
#'     \item For each treatment column tc:
#'           n_strata_{tc}, pct_strata_{tc},
#'           strata_{tc}_min, strata_{tc}_median, strata_{tc}_mean,
#'           strata_{tc}_max
#'     \item For each treatment column tc:
#'           L1_{tc}_before, L1_{tc}_after,
#'           per-covariate smd_{v}_{tc}_before/after, vr_{v}_{tc}_before/after
#'     \item n_ctrl_strata, pct_ctrl_strata
#'     \item L1_worst_before, L1_worst_after (max across treatment cols)
#'   }
gd_cem_quality_report <- function(cem_result) {

  dt_s <- cem_result$strata_summary
  dt_d <- cem_result$data
  cfg  <- cem_result$config

  ## identify covariate and history columns for balance assessment
  cov_cols <- names(cfg$covariate_cutpoints)
  hist_cols <- cfg$history_cols %||% character(0)
  all_balance_cols <- c(cov_cols, hist_cols)

  ## control coverage
  n_ctrl_strata <- sum(dt_s$n_control > 0)

  ## coverage stats per treatment
  l_cov <- map(cfg$treatment_cols, gd_cem_quality_treat_cov, dt_s = dt_s)

  ## balance stats per treatment (cov + hist vars, with separate L1 for each subset)
  l_bal <- if (length(all_balance_cols) > 0) {
             map(cfg$treatment_cols, gd_cem_quality_treat_bal,
                 dt_d = dt_d, covariate_cols = cov_cols, history_cols = hist_cols,
                 stratum_col = "stratum")
           } else list()

  ## keep this for debugging, do not delete this
  ## gd_cem_quality_treat_bal("exn_pm", dt_d = dt_d, covariate_cols = cov_cols, history_cols = hist_cols, stratum_col = "stratum")
    
  ## combine long balance data.tables and build flat columns
  dt_bal <- if (length(l_bal) > 0) rbindlist(l_bal) else data.table()

  l_bal_flat <- if (nrow(dt_bal) > 0) {
    dt_bal[, col := sprintf("%s_%s_%s_%s", measure, variable, treatment, stage)]
    as.list(setNames(dt_bal$value, dt_bal$col))
  } else list()

  ## build output
  l_out <- c(
    list(L                 = cfg$L,
         history_breaks    = cfg$history_breaks,
         history_nbins_str = paste(cfg$history_nbins, collapse = ","),
         n_prepped         = nrow(dt_d),
         n_strata          = nrow(dt_s),
         strata_median_size = as.integer(median(dt_s$n_total)),
         strata_mean_size   = round(mean(dt_s$n_total), 1),
         strata_min_size    = min(dt_s$n_total),
         strata_max_size    = max(dt_s$n_total),
         n_hist_str        = uniqueN(dt_d$hist_str)),
    as.list(unlist(l_cov)),
    l_bal_flat,
    list(
      n_ctrl_strata   = n_ctrl_strata,
      pct_ctrl_strata = round(n_ctrl_strata / nrow(dt_s), 4))
  )

  as.data.table(l_out)
}

#' Print CEM coverage for one treatment column (helper for diag).
#'
#' @param tc String. Treatment column name.
#' @param dt_q data.table. Quality report from gd_cem_quality_report.
#' @param dt_s data.table. Strata summary from gd_cem_strata.
gd_cem_diag_print_treat <- function(tc, dt_q, dt_s) {
  n_cur <- dt_q[[paste0("n_strata_", tc)]]
  p_cur <- dt_q[[paste0("pct_strata_", tc)]]
  cat(sprintf("\n  Strata w/ %s > 0  : %d / %d (%.1f%%)",
              tc, n_cur, nrow(dt_s), 100 * p_cur))
  if (!is.na(dt_q[[paste0("strata_", tc, "_min")]])) {
    cat(sprintf("\n    per stratum      : min=%d, median=%d, mean=%.1f, max=%d",
                dt_q[[paste0("strata_", tc, "_min")]],
                dt_q[[paste0("strata_", tc, "_median")]],
                dt_q[[paste0("strata_", tc, "_mean")]],
                dt_q[[paste0("strata_", tc, "_max")]]))
  }
}

#' Print-friendly summary of CEM strata results.
#'
#' @param cem_result List returned by gd_cem_strata.
#' @return The quality report data.table (invisibly), with a printed overview.
gd_cem_strata_diag <- function(cem_result) {
  dt_q <- gd_cem_quality_report(cem_result)
  dt_s <- cem_result$strata_summary
  cfg  <- cem_result$config

  cat(sprintf("\nCEM Strata Diagnostics"))
  cat(sprintf("\n  L (lags)          : %d", dt_q$L))
  cat(sprintf("\n  History breaks    : %s (nbins: %s)", cfg$history_breaks,
              paste(cfg$history_nbins, collapse = ", ")))
  cat(sprintf("\n  N (prepped)       : %d", dt_q$n_prepped))
  cat(sprintf("\n  N strata          : %d", dt_q$n_strata))
  cat(sprintf("\n  Strata size       : min=%d, median=%d, mean=%.1f, max=%d",
              dt_q$strata_min_size, dt_q$strata_median_size,
              dt_q$strata_mean_size, dt_q$strata_max_size))
  cat(sprintf("\n  Unique hist_str   : %d", dt_q$n_hist_str))

  walk(cfg$treatment_cols, gd_cem_diag_print_treat, dt_q = dt_q, dt_s = dt_s)

  cat(sprintf("\n  Strata w/ controls: %d / %d (%.1f%%)",
              dt_q$n_ctrl_strata, nrow(dt_s), 100 * dt_q$pct_ctrl_strata))
  cat("\n")

  invisible(dt_q)
}


#' Plot CEM quality report diagnostics.
#'
#' Produces a multi-panel ggplot showing before-after balance (SMD, VR, L1)
#' for each treatment column and stratum coverage. Requires ggplot2 and patchwork.
#'
#' @param cem_result Named list from \code{gd_cem_strata}.
#' @return A \code{patchwork} object with balance and coverage panels.
gp_cem_quality <- function(cem_result) {

  ## input validation
  cfg <- cem_result$config
  dt_q <- gd_cem_quality_report(cem_result)

  tcs      <- cfg$treatment_cols
  balance_names <- union(names(cfg$covariate_cutpoints), cfg$history_cols %||% character(0))

  ## build long-format balance data from single-row dt_q via CJ + map
  dt_balance <- if (length(balance_names) > 0) {
    CJ(stat = c("smd", "vr"), cov = balance_names,
       tc = tcs, stage = c("before", "after"), sorted = FALSE) %>%
      .[, col_nm := paste0(stat, "_", cov, "_", tc, "_", stage)] %>%
      .[, val := as.numeric(map(col_nm, ~dt_q[[.x]]))] %>%
      .[, col_nm := NULL] %>%
      .[!is.na(val) & !is.nan(val)]
  } else data.table(stat = character(), cov = character(), tc = character(), stage = character(), val = numeric())

  ## L1 data (only if L1_all columns exist in dt_q)
  ## dt_l1 <- if (paste0("L1_all_", tcs[1], "_before") %in% names(dt_q)) {
  ##   CJ(tc = tcs, stage = c("before", "after"), sorted = FALSE) %>%
  ##     .[, val := as.numeric(map2(tc, stage, ~dt_q[[paste0("L1_all_", .x, "_", .y)]]))]
  ## } else data.table(tc = character(), stage = character(), val = numeric())

  
  l_l1_cols <- c("type", "time", "treat")
  dt_l1 <- dt_q[, .SD, .SDcols = patterns("^L1")] %>% melt(measure.vars = names(.)) %>% 
    .[, `:=`(type = str_extract(variable, "_cov_|_hist_|_all_"),
             time = str_extract(variable, "_before|_after"),
             treat = str_extract(variable, paste0(paste0("_", tcs, "_"), collapse = "|")))] %>%
    .[is.na(treat), treat := "all"] %>%
    .[, (l_l1_cols) := map(.SD, trimws, whitespace = "_"), .SDcols = l_l1_cols]
      


  
  ## coverage data
  ## cov_n <- map_dbl(tcs, ~as.numeric(dt_q[[paste0("n_strata_", .x)]] %||% 0))
  cov_n <- sapply(tcs, function(tc) as.numeric(dt_q[[paste0("n_strata_", tc)]] %||% 0))
  dt_cov <- data.table(category = c(tcs, "none"),
                       n = c(cov_n, as.numeric(dt_q$n_ctrl_strata %||% 0)))
  dt_cov[, pct := n / dt_q$n_strata]

  ## -- SMD Love plot --
  dt_smd <- dt_balance[stat == "smd"]

  if (nrow(dt_smd) == 0) {
    p_smd <-  ggplot() + labs(title = "Standardized Mean Difference (no covariates)")
  }

  if (nrow(dt_smd > 0)) {

    p_smd <- ggplot(dt_smd, aes(x = abs(val), y = cov, color = stage, shape = stage)) +
      geom_point(size = 2.5) + # , position = position_dodge(width = 0.5)) +
      geom_vline(xintercept = 0, linetype = "dotted", alpha = 0.5) +
      ## geom_vline(xintercept = 0.1, linetype = "dashed", alpha = 0.5) +
      facet_grid(tc~., scales = "free_y", switch = "y") +
      labs(title = "Standardized Mean Difference", x = "|SMD|", y = NULL,
           color = NULL, shape = NULL) +
      theme(legend.position = "bottom", plot.title = element_text(hjust = 0.5),
            strip.text.y.left = element_text(angle = 0))
    
  } 
    

  ## -- VR plot --
  dt_vr <- dt_balance[stat == "vr"]
  if (nrow(dt_vr) == 0) {
    p_vr <- ggplot() + labs(title = "Variance Ratio (no covariates)") 
  }

  if (nrow(dt_vr) > 0) {

    p_vr <- ggplot(dt_vr, aes(x = val, y = cov, color = stage, shape = stage)) +
      geom_point(size = 2.5, position = position_dodge(width = 0.5)) +
      geom_vline(xintercept = 1, linetype = "dashed", alpha = 0.5) +
      facet_grid(tc~., scales = "free_y") +
      labs(title = "Variance Ratio", x = "VR", y = NULL, color = NULL, shape = NULL) +
      theme(legend.position = "bottom", plot.title = element_text(hjust = 0.5))
    
  } 

  ## -- L1 bar plot --
  ## p_l1 <- ggplot(dt_l1, aes(x = tc, y = val, fill = stage)) +
  ##   geom_col(position = "dodge", width = 0.6) +
  ##   labs(title = "Multivariate L1 Imbalance", x = NULL, y = "L1", fill = NULL) +
  ##   theme(legend.position = "bottom", plot.title = element_text(hjust = 0.5))

  p_l1 <- dcast(dt_l1, treat + type ~ time, value.var = "value") %>%
    ggplot(aes(x= treat, ymin = before, ymax = after, color = type)) + 
    geom_linerange(position = position_dodge(width = 0.6), linewidth = 1) +
    geom_hline(yintercept = 0, linetype = "dashed")


  ggplot(dt_l1, aes(x = treat, y = value, fill = interaction(type, time))) + 
    geom_col(position = "dodge", width = 0.6)

  ## -- coverage pie --
  p_cov <- ggplot(dt_cov, aes(x = category, y = pct, fill = category)) +
    geom_col(show.legend = F) + # coord_polar(theta = "y") +
    labs(title = "Stratum Coverage", fill = NULL) +
    ## theme_void() +
    theme(plot.title = element_text(hjust = 0.5)) +
    geom_text(aes(label = sprintf("%.0f%%", 100 * pct)),
              position = position_stack(vjust = 1))

  patchwork::wrap_plots(p_smd, p_vr, p_l1, p_cov, ncol = 2) +
  patchwork::plot_layout(guides = "collect") + 
    patchwork::plot_annotation(
      title = "CEM Strata Balance Diagnostics",
      caption = sprintf("N prepped: %d | N strata: %d | Strata w/ controls: %d (%.0f%%)",
                        dt_q$n_prepped, dt_q$n_strata,
                        dt_q$n_ctrl_strata, 100 * dt_q$pct_ctrl_strata))

}

# =============================================================================
# Pre-treatment Trend Balance Diagnostics
# =============================================================================
# These functions check the parallel pre-trends assumption for DiD. The idea:
# within viable strata (both treated and control), we compare treated vs
# control on outcome variables at each pre-treatment relative year r.
# 
# Even if cumulative histories match (via coarsened hist_str), per-year
# outcome trajectories might diverge — e.g. two artists could reach the
# same cumulative count by very different paths (a gradual ramp vs a
# sudden spike). Checking per-year outcome balance reveals this.
#
# The CEM ATT weights ensure we're computing a within-stratum comparison,
# aggregated across strata. This is the same logic as gd_cem_quality_treat_bal,
# but on pre-treatment outcome years rather than contemporaneous covariates.

#' Compute pre-treatment balance for one treatment contrast and one relative year.
#'
#' Identifies viable strata (both treated and control exist) for a single
#' treatment column, computes within-stratum ATT weights, merges outcome
#' values at the lagged year, and returns before/after balance via
#' \code{gd_bal_stage}. This is a standalone helper so that each \code{(tc, r)}
#' combination can be debugged or tested in isolation.
#'
#' @param tc String. Treatment column name (defines the contrast).
#' @param r Negative integer. Pre-treatment year offset (\code{-1}, \code{-2}, ...).
#' @param dt_d data.table. CEM result data (from \code{cem_result$data}).
#'   Must have \code{cfg$uid}, \code{cfg$tid}, and \code{stratum} columns.
#' @param dt_full data.table. Full panel for merging outcome values.
#' @param outcome_vars Character vector. Outcome column names to check.
#' @param cfg Config list from \code{cem_result$config}.
#' @return A long data.table with columns (variable, measure, treatment,
#'   stage, value, relative_year), or empty if no viable data.
gd_pre_trend_one <- function(tc, r, dt_d, dt_full, outcome_vars, cfg) {

  ## identify viable strata (both treated and control)
  treat_v <- as.integer(dt_d[[tc]] > 0)
  if (sum(treat_v) == 0) return(data.table())

  dt_strat <- dt_d[, .(n1 = sum(get(tc) > 0), n0 = sum(get(tc) == 0)),
                    by = "stratum"]
  viable_strata <- dt_strat[n1 > 0 & n0 > 0, stratum]
  viable_idx <- dt_d$stratum %in% viable_strata
  if (!any(viable_idx)) return(data.table())

  ## subset to viable obs and compute CEM ATT weights
  dt_v <- dt_d[viable_idx]
  t_v <- treat_v[viable_idx]

  dt_sz <- dt_v[, .(n1 = sum(get(tc) > 0), n0 = sum(get(tc) == 0)),
                 by = "stratum"]
  mT <- sum(dt_sz$n1)
  mC <- sum(dt_sz$n0)
  dt_v[dt_sz, on = "stratum", `:=`(.n1 = i.n1, .n0 = i.n0)]
  w_att <- dt_v[, fifelse(t_v == 1, 1, (mC / mT) * (.n1 / .n0))]

  ## merge outcome values at the lagged year
  dt_lookup <- data.table(
    lookup_uid  = dt_v[[cfg$uid]],
    lookup_year = as.integer(dt_v[[cfg$tid]] + r),
    treat       = t_v,
    weight      = w_att
  )
  setnames(dt_lookup,
           old = c("lookup_uid", "lookup_year"),
           new = c(cfg$uid, "year"))

  dt_outcome <- merge(
    dt_lookup,
    dt_full[, c(cfg$uid, "year", outcome_vars), with = FALSE],
    by = c(cfg$uid, "year"),
    all.x = TRUE
  )

  ## drop obs with missing outcomes (artist too young for this lag)
  dt_outcome <- collapse::na_omit(dt_outcome, cols = outcome_vars)
  if (nrow(dt_outcome) == 0) return(data.table())

  ## compute before (uniform) and after (CEM ATT) balance — only SMD needed
  w_u <- rep(1, nrow(dt_outcome))
  dt_before <- gd_bal_stage(dt_outcome, outcome_vars, character(), character(),
                             dt_outcome$treat, w_u, tc, "before", b_full = FALSE)
  dt_after  <- gd_bal_stage(dt_outcome, outcome_vars, character(), character(),
                             dt_outcome$treat, dt_outcome$weight, tc, "after", b_full = FALSE)

  rbind(dt_before, dt_after)[, relative_year := r]
}


#' Compute pre-treatment outcome balance across treatments and years.
#'
#' Produces a flat grid of all (treatment_contrast, relative_year) combos
#' and calls \code{gd_pre_trend_one} for each.  The result is a single long
#' data.table ready for \code{gp_pre_trend}.
#'
#' @inheritParams gd_pre_trend_one
#' @param cem_result List returned by \code{gd_cem_strata}.
#' @param max_lags Integer. Number of pre-treatment years to check.
#'   Defaults to the config's \code{L}.
#' @return Long data.table with columns (variable, measure, treatment,
#'   relative_year, stage, value).
gd_pre_trend_balance <- function(cem_result, dt_full, outcome_vars = NULL,
                                  max_lags = NULL) {

  cfg <- cem_result$config
  dt_d <- cem_result$data

  if (is.null(max_lags))    max_lags    <- cfg$L
  if (is.null(outcome_vars)) outcome_vars <- cfg$treatment_cols

  ## build a flat grid of all (treatment_contrast, relative_year) combos
  dt_grid <- CJ(tc = cfg$treatment_cols, r = -seq_len(max_lags), sorted = FALSE)

  ## DEBUG
  ## gd_pre_trend_one("exn_pm", -1, dt_d, dt_full, outcome_vars, cfg) %>% print(n=80)

  rbindlist(map2(dt_grid$tc, dt_grid$r, ~gd_pre_trend_one(.x, .y, dt_d, dt_full,
                                                           outcome_vars, cfg)),
            fill = TRUE)
}


#' Plot pre-treatment trend balance.
#'
#' Produces a faceted plot of SMD by relative year for each outcome variable
#' and treatment contrast. A flat line near zero suggests parallel pre-trends.
#' Lines moving away from zero as \code{|r|} increases suggest pre-treatment
#' divergence.
#'
#' @param dt_pre_bal Long data.table from \code{gd_pre_trend_balance}.
#' @param n_col Number of facet columns (default 2).
#' @return A \code{patchwork} or \code{ggplot} object.
gp_pre_trend <- function(dt_pre_bal, n_col = 2) {

  ## only plot SMD — the most interpretable metric for trends
  dt_smd <- dt_pre_bal[measure == "smd" & !is.na(value)]

  if (nrow(dt_smd) == 0) {
    return(ggplot() + labs(title = "Pre-trend Balance (no data)"))
  }

  ## plot SMD by relative year, one panel per (treatment, variable) combo
  ggplot(dt_smd, aes(x = relative_year, y = value,
                      color = stage, group = stage,
                      shape = stage)) +
    geom_line() +
    geom_point(size = 2) +
    geom_hline(yintercept = 0, linetype = "dashed", alpha = 0.5) +
    ## reference: |SMD| < 0.1 is the conventional threshold
    geom_hline(yintercept = c(-0.1, 0.1), linetype = "dotted",
               alpha = 0.3, linewidth = 0.5) +
    ## facet_wrap(treatment ~ variable, ncol = n_col, scales = "free_y") +
    facet_grid(treatment ~ variable, scales = "free_y") +
    scale_x_continuous(breaks = scales::pretty_breaks()) +
    labs(title = "Pre-treatment Outcome Balance by Relative Year",
         subtitle = "SMD between treated and control, by year before treatment",
         x = "Years before treatment",
         y = "Standardized Mean Difference",
         color = NULL, shape = NULL) +
    theme(legend.position = "bottom",
          plot.title = element_text(hjust = 0.5),
          plot.subtitle = element_text(hjust = 0.5, size = 9))

}

# =============================================================================
# Outcome Lead Columns (for DiD estimation)
# =============================================================================
# These functions augment CEM strata data with future (lead) outcome values.
# For each observation in cem_result$data, we merge the outcome value at
# year + k for k = 1, 2, ... to create columns like exn_pi_n1, exn_pi_n2, etc.
# These can then be used as dependent variables in a DiD model:
#   feols(exn_pi_n1 ~ treat_PM | stratum, data, weights = ~weight)

#' Add lead outcome columns to a CEM result for DiD estimation.
#'
#' For each observation in \code{cem_result$data}, merges outcome values at
#' \code{year + k} from the full panel and names them \code{{var}_n{k}}.
#' Observations beyond the panel (e.g. last year with no \code{year + 3} row)
#' get \code{NA} — these are dropped automatically by \code{feols}.
#'
#' @param cem_result List returned by \code{gd_cem_strata}. Must have a
#'   \code{$data} slot and a \code{$config} with \code{uid} and \code{tid}.
#' @param dt_full Full panel data.table containing at least the \code{uid},
#'   \code{tid}, and \code{outcome_vars} columns.
#' @param outcome_cols Named list mapping outcome variable names (strings) to
#'   the number of lead years (integers).  E.g. \code{list(exn_pi = 3, exn_pm = 3)}
#'   creates columns \code{exn_pi_n1}, \code{exn_pi_n2}, \code{exn_pi_n3},
#'   \code{exn_pm_n1}, \code{exn_pm_n2}, \code{exn_pm_n3}.
#' @return The same \code{cem_result} list with additional lead columns in
#'   \code{$data}. The list is returned invisibly (modified by reference).
gd_add_outcome_next <- function(cem_result) { # , dt_full, outcome_cols) {

  cfg <- cem_result$config
  dt_d <- cem_result$data 

  dt_full <- cem_result$config$dt_panel
  outcome_cols <- cfg$outcome_cols

  ## maximum number of lead years across all outcomes
  max_k <- max(as.integer(outcome_cols))

  ## iterate over k = 1..max_k, merging outcome values at year + k
  for (k in seq_len(max_k)) {

    ## which outcomes need this lead?
    vars_k <- names(outcome_cols)[as.integer(outcome_cols) >= k]
    if (length(vars_k) == 0) next

    ## build lookup: (uid, year + k) for the merge
    dt_lookup <- data.table(uid_lkp = dt_d[[cfg$uid]],
                            yr_lkp  = as.integer(dt_d[[cfg$tid]] + k)) %>% 
      setnames(old = c("uid_lkp", "yr_lkp"), new = c(cfg$uid, "year"))

    ## merge with full panel to get outcome values k years ahead
    dt_merged <- merge(dt_lookup, dt_full[, c(cfg$uid, "year", vars_k), with = FALSE],
      by = c(cfg$uid, "year"), all.x = TRUE)

    ## assign lead columns back to dt_d
    new_cols <- paste0(vars_k, "_n", k)
    ## dt_d[, (new_cols) := dt_merged[, ..vars_k]]
    dt_d[, (new_cols) := dt_merged[, .SD, .SDcols = vars_k]]
  }

  ## return invisibly (modified by reference)
  invisible(cem_result)
}
